"""Optimistic locking document store."""

from typing import Any, Dict, Optional
from record import VersionedRecord


class OptimisticStore:
    def __init__(self):
        self._store: Dict[str, VersionedRecord] = {}

    def insert(self, record_id: str, data: Dict[str, Any]) -> VersionedRecord:
        rec = VersionedRecord(record_id, dict(data), version=1)
        self._store[record_id] = rec
        return rec

    def get(self, record_id: str) -> Optional[VersionedRecord]:
        rec = self._store.get(record_id)
        if rec:
            return VersionedRecord(rec.record_id, dict(rec.data), rec.version)
        return None

    def update(self, record_id: str, new_data: Dict[str, Any], expected_version: int) -> bool:
        curr = self._store.get(record_id)
        if not curr:
            return False

        # BUG: Overwrites curr.data immediately BEFORE checking version!
        curr.data = dict(new_data)
        if curr.version != expected_version:
            return False

        curr.version += 1
        return True

repo_files.session.py:
"""Data session worker updating shared records."""

from typing import Any, Dict
from storage import OptimisticStore


class DocumentSession:
    def __init__(self, store: OptimisticStore):
        self.store = store

    def patch_document(self, record_id: str, field_updates: Dict[str, Any]) -> bool:
        rec = self.store.get(record_id)
        if not rec:
            return False
        merged = dict(rec.data)
        merged.update(field_updates)
        return self.store.update(record_id, merged, rec.version)

